        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='ts-config-service' AND level IN ('ERROR','SEVERE') GROUP BY 1,2,3 ORDER BY n DESC", "claim": "Config logs HikariPool connection timeouts (30000ms) and 'Unable to acquire JDBC Connection' / communications link failure errors."},
        {"kind": "metric", "sql": "SELECT metric, count(*) n, round(avg(value),2) avgv, round(max(value),2) maxv FROM abnormal_metrics WHERE service_name='ts-config-service' AND metric='container.cpu.usage' GROUP BY 1", "claim": "Config container CPU stays low (avg about 0.06), so the failure is not CPU saturation."}
